sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // MSSCUSTODY-5853 - This BR will update the GHSS outbound record and update the task on receiving Amend Inbound from EL.
    try {


        var addtionalAttributes = JSON.parse(current.additional_attributes);
        var linkMaintenance = addtionalAttributes.link_maintenance ? addtionalAttributes.link_maintenance.toString().trim() : "";
        var linkType = addtionalAttributes.link_type ? addtionalAttributes.link_type.toString().trim() : "";
        var delinkTaskID = addtionalAttributes.servicenowid ? addtionalAttributes.servicenowid.toString().trim() : "";

        //Self delink logic
        // Parse the payload
        var payLoadParser = new global.JSON.parse(current.payload);

        // Extract value from inbound record fields
        var taskSysID = current.message_id;
        var eventDate = current.event_date_time;
        /*var gdt = new GlideDateTime(eventDateTime); // Parse the event_date_time
        eventDate = gdt.getLocalDate().toString();*/ // Extract only the date portion

        // Extract required values
        var ghssMessage = payLoadParser.ghss_message;
        var rpaMessage = payLoadParser.rpa_message;
        var responseStatus = current.event_status;
        var additionalAttribute = current.additional_attributes;


        var getOutBoundRec = new GlideRecord("x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table");
        if (linkMaintenance == "D" && linkType == "Self De-Link") {
            getOutBoundRec.addEncodedQuery("request_bodyLIKE" + delinkTaskID);
        } else {
            getOutBoundRec.addEncodedQuery("sn_task.sys_idSTARTSWITH" + taskSysID);
            gs.info('amend-widget-in');
        }
        getOutBoundRec.orderByDesc('sys_created_on');
        getOutBoundRec.setLimit(1);
        getOutBoundRec.query();
        if (getOutBoundRec.next()) {
            var getDetails = JSON.parse(getOutBoundRec.request_body);
            var bulkStatus = getDetails.HEADER.additionalattributes.bulk;

            if (linkMaintenance == "D" && linkType == "Self De-Link") {
                taskSysID = getOutBoundRec.sn_task.sys_id;
            }

        }


        if (taskSysID) {
            // Update GHSS Outbound Record and Close task
            var updateOutboundRec = new x_hsb11_mss_c_ghss.MSSGHSSAmendUtils().updateOutboundRecord(payLoadParser, taskSysID, responseStatus, ghssMessage, rpaMessage, eventDate, bulkStatus, additionalAttribute);
        }

    } catch (e) {
        gs.error('Error in parsing EL RPA Amend payload: ' + e.message + ', Stack: ' + e.stack);
    }

})(current, previous);
